"""Bundled Glasshouse client. Kept buildless so `replicanta --web` stays local."""

APP_HTML = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Replicanta Glasshouse</title><link rel="stylesheet" href="/app.css"></head><body><header><b><i>R</i> REPLICANTA <em>glasshouse</em></b><nav><button data-view="habitat" class="on">Habitat</button><button data-view="atlas">Mind atlas</button><button data-view="memory">Timeline</button></nav><span id="local">● local</span><button id="still">Stillness</button></header><aside id="nursery"><small>NURSERY</small><div id="orgs"></div><button id="new">＋ Grow a new mind</button></aside><main><section id="heading"><small>HABITAT · <span data-name></span></small><h1>A mind in cultivation.</h1><p>Everything it senses, remembers, and changes remains visible to you.</p></section><section id="habitat" class="view on"><div class="specimen card"><small>LIVE SPECIMEN <span id="state"></span></small><div class="field"><div class="rings"></div><div class="orb"><span data-name></span></div></div><div class="meters"><label>Mood <b id="mood"></b></label><label>Stress <b id="stress"></b></label><label>Grounding <b id="ground"></b></label><label>Chaos <input id="chaos" type="range" min="0" max="1" step=".05"></label></div></div><div class="chat card"><h2>Conversation</h2><div id="messages"></div><form id="chat"><textarea aria-label="Message" placeholder="Teach, ask, or wonder aloud…"></textarea><button>↑</button></form></div></section><section id="atlas" class="view"><div id="beliefs" class="card list"></div></section><section id="memory" class="view"><div id="episodes" class="card list"></div></section></main><aside id="steward"><h2>Stewardship</h2><p>You remain in control.</p><label>Auto-apply mutations <input id="auto" type="checkbox"></label><label>Attention <input id="focus" placeholder="Guide attention"></label><div id="mutation"></div><button id="sleep">Sleep / wake</button><p class="warning">AI-generated output may be wrong. This interface does not indicate consciousness.</p></aside><dialog id="trace"><button id="close">×</button><small>OPEN LENS</small><h2>Cognitive trace</h2><p>This is a process summary, not hidden reasoning or proof of consciousness.</p><ol><li>Perceived your message</li><li>Extracted learnable facts</li><li>Recalled relevant beliefs and skills</li><li>Considered candidate responses</li><li>Recorded resulting changes</li></ol></dialog><script src="/app.js"></script></body></html>'''

APP_CSS = r''':root{--p:#f3f0e7;--i:#17251e;--g:#174235;--m:#687068;--l:#dfe6d8}*{box-sizing:border-box}body{margin:0;background:var(--p);color:var(--i);font:14px Arial;display:grid;grid-template:64px 1fr/190px 1fr 250px;min-height:100vh}header{grid-column:1/-1;display:flex;align-items:center;gap:30px;padding:0 20px;border-bottom:1px solid #0002}header b{letter-spacing:2px}header b i{display:inline-grid;place-items:center;background:var(--g);color:white;border-radius:50%;width:28px;height:28px;font:16px Georgia}header em{font:12px Georgia;color:var(--m);letter-spacing:0}nav{display:flex;height:100%}button{cursor:pointer}nav button{border:0;background:none;padding:0 16px;color:var(--m)}nav button.on{border-bottom:2px solid var(--g);color:var(--g)}#local{margin-left:auto;color:#478052;font-size:11px}#still{border:1px solid var(--g);background:none;padding:8px 12px;color:var(--g)}aside{padding:28px 15px;border-right:1px solid #0002}aside#steward{border-right:0;border-left:1px solid #0002}aside small,main>section>small{letter-spacing:2px;font-size:9px;color:var(--m)}#orgs button,#new{width:100%;text-align:left;border:0;background:none;padding:12px;margin-top:8px}#orgs button.on{background:#dfe1d7}#orgs b{font:15px Georgia}#orgs span{display:block;font-size:9px;color:var(--m)}main{padding:35px;min-width:0}h1{font:34px Georgia;margin:8px 0}#heading p{font:italic 14px Georgia;color:var(--m)}.view{display:none}.view.on{display:grid}.view#habitat{grid-template-columns:.8fr 1.2fr;gap:14px}.card{border:1px solid #0002;background:#fff7}.specimen>small{display:flex;justify-content:space-between;padding:14px}.field{height:330px;display:grid;place-items:center;background:linear-gradient(#1742350b 1px,transparent 1px),linear-gradient(90deg,#1742350b 1px,transparent 1px);background-size:24px 24px;overflow:hidden}.orb{width:145px;height:145px;border-radius:45% 55%;background:radial-gradient(circle at 35% 30%,#e2ed9d,#75a16b 30%,#174235 75%);box-shadow:0 0 45px #527c5a66;display:grid;place-items:center;color:#eef5d2;animation:breathe 5s infinite}.rings{position:absolute;width:220px;height:180px;border:1px solid #17423533;border-radius:50%;animation:spin 15s linear infinite}.meters{display:grid;grid-template-columns:1fr 1fr}.meters label{padding:14px;border-top:1px solid #0002;font-size:10px}.meters b{float:right;font:12px Georgia}.chat{display:flex;flex-direction:column;height:490px}.chat h2{font:14px Georgia;padding:14px;margin:0;border-bottom:1px solid #0002}#messages{padding:16px;overflow:auto;flex:1}.msg{max-width:85%;background:#e3e0d6;padding:12px;margin:10px 0;font:14px/1.5 Georgia}.msg.org{background:var(--l);border-left:2px solid var(--g)}.msg button{display:block;border:0;border-top:1px solid #0002;background:none;color:var(--g);font-size:9px;margin-top:8px;padding-top:8px}form{display:grid;grid-template-columns:1fr 35px;border-top:1px solid #0002;padding:10px}textarea{border:0;background:none;resize:none;outline:0;padding:8px}form button{border:0;border-radius:50%;background:var(--g);color:white;width:32px;height:32px}.list article{padding:16px;border-bottom:1px solid #0002;display:grid;grid-template-columns:1fr auto}.list h3{font:16px Georgia;margin:0}.list p{color:var(--m);font-size:11px}.list b{font:14px Georgia}#steward h2{font:20px Georgia;margin:0}#steward>p{color:var(--m);font-size:10px}#steward label{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #0002;padding:14px 0;font:12px Georgia}#focus{width:100px}.mutation{background:#eee4c9;padding:12px;margin:15px 0}.mutation b{font:14px Georgia}.mutation button{margin:8px 4px 0 0}.warning{margin-top:30px!important;line-height:1.5}dialog{border:0;width:min(480px,90vw);padding:30px;box-shadow:0 20px 80px #0005}dialog::backdrop{background:#15271fcc}dialog #close{float:right;border:0;background:none;font-size:24px}dialog h2{font:28px Georgia}dialog li{padding:10px;border-top:1px solid #0002}body.still .orb,body.still .rings{animation-play-state:paused;filter:grayscale(1)}@keyframes breathe{50%{transform:scale(1.05) rotate(2deg)}}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:900px){body{display:block}header{height:60px;position:sticky;top:0;background:var(--p);z-index:2}header nav{display:none}aside{display:none}main{padding:20px}.view#habitat{grid-template-columns:1fr}.chat{height:520px}}'''

APP_JS = r'''const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];let state;
async function api(path,data){const r=await fetch('/api/'+path,{method:data?'POST':'GET',headers:{'Content-Type':'application/json'},body:data?JSON.stringify(data):null});const j=await r.json();if(!r.ok)throw Error(j.error);return j}
function render(s){state=s;$$('[data-name]').forEach(x=>x.textContent=s.organism.name);$('#state').textContent=s.organism.state.toUpperCase();$('#mood').textContent=s.organism.mood;$('#stress').textContent=s.organism.stress;$('#ground').textContent=s.organism.rationality;$('#chaos').value=s.organism.chaos;$('#auto').checked=s.organism.auto_apply;$('#messages').innerHTML=s.chat.map(m=>`<div class="msg ${m.role==='org'?'org':''}"><small>${m.role==='org'?s.organism.name:'YOU'}</small><div>${esc(m.text)}</div>${m.role==='org'?'<button class="why">⌁ How did this form?</button>':''}</div>`).join('');$('#messages').scrollTop=1e9;$('#beliefs').innerHTML='<h2>What this mind holds to be true</h2>'+s.beliefs.map(b=>`<article><div><h3>${esc(b.subject)} <em>${esc(b.relation)}</em> ${esc(b.value)}</h3><p>Inspectable symbolic belief</p></div><b>${Math.round(b.confidence*100)}%</b></article>`).join('');$('#episodes').innerHTML='<h2>Developmental timeline</h2>'+s.memory.map(e=>`<article><div><h3>${esc(e.kind)}</h3><p>${esc(e.text)}</p></div><b>cycle ${e.cycle}</b></article>`).join('');$('#orgs').innerHTML=s.nursery.organisms.map(n=>`<button data-org="${esc(n)}" class="${n===s.organism.name?'on':''}"><b>${esc(n)}</b><span>${n===s.organism.name?s.organism.state:'stored'}</span></button>`).join('');const p=s.extensions.pending;$('#mutation').innerHTML=p?`<div class="mutation"><small>PENDING MUTATION</small><p><b>${esc(p.kind)}</b></p><button data-mut="approve">Approve</button><button data-mut="reject">Reject</button></div>`:'';bindDynamic()}
function esc(x){const d=document.createElement('div');d.textContent=String(x??'');return d.innerHTML}function bindDynamic(){$$('.why').forEach(b=>b.onclick=()=>$('#trace').showModal());$$('[data-org]').forEach(b=>b.onclick=async()=>render(await api('swap',{name:b.dataset.org})));$$('[data-mut]').forEach(b=>b.onclick=async()=>render((await api('mutation',{action:b.dataset.mut})).state))}
$$('[data-view]').forEach(b=>b.onclick=()=>{$$('[data-view],.view').forEach(x=>x.classList.remove('on'));b.classList.add('on');$('#'+b.dataset.view).classList.add('on')});$('#close').onclick=()=>$('#trace').close();$('#chat').onsubmit=async e=>{e.preventDefault();const t=$('textarea');if(!t.value.trim())return;t.disabled=true;try{render((await api('chat',{text:t.value})).state);t.value=''}catch(x){alert(x.message)}finally{t.disabled=false;t.focus()}};$('#chaos').onchange=async e=>render(await api('settings',{chaos:Number(e.target.value)}));$('#auto').onchange=async e=>render(await api('settings',{auto_apply:e.target.checked}));$('#focus').onchange=async e=>render(await api('settings',{focus:e.target.value}));$('#sleep').onclick=async()=>render((await api('lifecycle',{action:state.organism.state==='wake'?'sleep':'wake'})).state);$('#still').onclick=()=>{document.body.classList.toggle('still');$('#still').textContent=document.body.classList.contains('still')?'Resume':'Stillness'};$('#new').onclick=async()=>{const n=prompt('Name the new organism');if(n)try{render(await api('organisms',{name:n}))}catch(x){alert(x.message)}};api('state').then(render).catch(x=>document.body.innerHTML='<p>'+esc(x.message)+'</p>');'''
